// The subset of named character references we decode. HTML defines a much
// larger table, but for the purpose of resolving resource references inside
// text nodes and attribute values these cover the characters that carry
// syntactic meaning (`&`, `<`, `>`, `"`, `'`) plus the non-breaking space.
const NAMED_CHARACTER_REFERENCES = new Map([
	["amp", "&"],
	["lt", "<"],
	["gt", ">"],
	["quot", '"'],
	["apos", "'"],
	["nbsp", " "]
]);

// Matches a well-formed hexadecimal (`&#x41;` / `&#X41;`), decimal
// (`&#65;`) or named (`&amp;`) character reference. Each numeric form
// requires at least one digit, so malformed/empty references such as
// `&#;` or `&#x;` never match and are therefore left untouched. A bare
// `&` (not followed by a valid reference) also never matches.
const CHARACTER_REFERENCE_REGEXP =
	/&(#[xX][0-9a-fA-F]+|#[0-9]+|[a-zA-Z][a-zA-Z0-9]*);/g;

/**
 * Decode HTML character references (named, decimal and hexadecimal) in a
 * raw string back to their actual character values. Unknown named
 * references, malformed/empty numeric references and bare ampersands are
 * left unchanged.
 * @param {string} input raw string possibly containing character references
 * @returns {string} the string with recognized character references decoded
 */
const decodeHtmlEntities = (input) => {
	if (input.indexOf("&") === -1) {
		return input;
	}

	return input.replace(CHARACTER_REFERENCE_REGEXP, (match, body) => {
		// Numeric character reference (`#…`).
		if (body.charCodeAt(0) === 0x23 /* # */) {
			const second = body.charCodeAt(1);
			/** @type {number} */
			let codePoint;
			if (second === 0x78 /* x */ || second === 0x58 /* X */) {
				codePoint = Number.parseInt(body.slice(2), 16);
			} else {
				codePoint = Number.parseInt(body.slice(1), 10);
			}
			if (Number.isNaN(codePoint)) {
				return match;
			}
			try {
				return String.fromCodePoint(codePoint);
			} catch (_err) {
				// Out-of-range code point — leave the reference untouched.
				return match;
			}
		}

		// Named character reference.
		const decoded = NAMED_CHARACTER_REFERENCES.get(body);
		return decoded !== undefined ? decoded : match;
	});
};

